const app=document.querySelector('#app');
const tvCode=new URLSearchParams(location.search).has('tv')?(new URLSearchParams(location.search).get('tv')||'').toUpperCase():null;
const storage={get(k){try{return JSON.parse(localStorage.getItem(k));}catch{return null;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch{}},remove(k){try{localStorage.removeItem(k);}catch{}}};
const savedMatch=storage.get('teklif-match');
let localSeries=savedMatch?.series||null,playPlan={mode:'playlist',playlist:['heroes'],rounds:5},playlistPick='heroes',rankDraft={},rankKey='',localVoter=null,voteRounds=5,configQueue=Promise.resolve();
const sounds=createSounds(storage.get('teklif-sound')!==false);
const announcer=createAnnouncer();
let noticeTimer,noticeSettingsOpen=false;
const turnNotice=createTurnNotice({preferences:storage.get('teklif-turn-notice')||{},play:kind=>sounds.play(kind),onNotice:showTurnNotice});
function showTurnNotice(name){clearTimeout(noticeTimer);const el=document.querySelector('#turn-notice');if(!el)return;el.classList.toggle('visible',!!name);el.textContent=name?`Açılış sende! · ${name}`:'';if(name)noticeTimer=setTimeout(()=>el.classList.remove('visible'),2400);}
let settings={categoryId:'heroes',variant:'all',slots:5,budget:20,timerSeconds:10,pricePerformance:false,jokers:false,scoring:'debate'},mode='local',group='Hepsi',count=2;
let names=['Ömer','Oyuncu 2','Oyuncu 3','Oyuncu 4','Oyuncu 5','Oyuncu 6'],myName='',roomCode=new URLSearchParams(location.search).get('room')||'';
let screen='home',transport='local',localGame=savedMatch?.game||storage.get('teklif-local'),room=null,session=storage.get('teklif-session'),network=[],busy=false,connectionError=false,lastSnapshot='',toastTimer,confirmAction=null;
let homeStage=roomCode?'setup':'categories',advancedOpen=false,categoryQuery='';
let clockOffset=0,seenActivity='',animationUntil=0;
if(localGame)prepareTimer(localGame);
