function saveLocal(){storage.set('teklif-local',localGame);storage.set('teklif-match',{game:localGame,series:localSeries});}
function currentSeries(){return transport==='local'?localSeries:room?.series;}
function syncLocal(){const state={game:localGame,series:localSeries};if(syncMatch(state)){localGame=state.game;localSeries=state.series;saveLocal();return true;}return false;}
function configureLobby(){if(transport!=='lan'||screen!=='lobby'||!room?.host)return;const code=session.code,payload={settings:{...settings},playPlan:{...playPlan,playlist:[...playPlan.playlist]}};configQueue=configQueue.catch(()=>{}).then(async()=>{try{const data=await api(`/api/rooms/${code}/configure`,{method:'POST',body:JSON.stringify(payload)});if(session?.code===code&&screen==='lobby')applyRoom(data);}catch(error){toast(error.message);}});}
function toast(message){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function categoryOptions(){return categories.map(c=>`<option value="${c.id}" ${settings.categoryId===c.id?'selected':''}>${esc(c.name)}</option>`).join('');}
function variantField(){if(settings.categoryId!=='heroes')return '';const c=categoryById('heroes');return `<div><label for="variant">Kahraman evreni</label><select id="variant" name="variant">${['all','Marvel','DC','The Boys','Invincible'].map(v=>{const n=v==='all'?c.cards.length:c.cards.filter(card=>card.universe===v).length;return `<option value="${v}" ${settings.variant===v?'selected':''}>${v==='all'?'Karışık evrenler':v} · ${n} kart</option>`;}).join('')}</select></div>`;}
function cover(c){return c.id==='heroes'?(c.cards.find(card=>card.name==='Venom')||c.cards[0]):c.cards[0];}
function photoNote(card){const a=imageCards[card.id];return a?.kind==='artist'?`<span class="photo-note">Sanatçı görseli · ${esc(a.subject)}</span>`:'';}
function photo(card,cls='',eager=false){return `<div class="photo ${cls}"><img src="/api/image/${encodeURIComponent(card.id)}?v=${imageCards[card.id]?.version||'1'}" alt="${esc(card.name+(imageCards[card.id]?.appearance?' · '+imageCards[card.id].appearance:''))}" loading="${eager?'eager':'lazy'}" decoding="async"><span class="photo-unavailable" hidden>Görsel henüz eklenmedi</span></div>`;}
function choices(name,label,options){return `<fieldset class="choice-field"><legend>${label}</legend><div class="choice-row">${options.map(([value,title])=>`<label class="choice ${String(settings[name])===String(value)?'selected':''}"><input type="radio" name="${name}" value="${value}" ${String(settings[name])===String(value)?'checked':''}>${title}</label>`).join('')}</div></fieldset>`;}
function settingsFields(withCategory=false){return `${screen==='lobby'||mode==='create'?`<label class="tv-option"><span><strong>TV’de oyna</strong><small>Büyük ekranda açık artırma, telefonlarda kumanda.</small></span><input type="checkbox" name="television" ${settings.television?'checked':''}></label>`:''}${withCategory?`<div><label for="categoryId">Kategori</label><select id="categoryId" name="categoryId">${categoryOptions()}</select></div>`:`<input type="hidden" name="categoryId" value="${settings.categoryId}">`}<details class="game-options" ${advancedOpen?'open':''}><summary><span>Oyun ayarları<small>${settings.slots} kart · ${settings.budget} jeton · ${settings.scoring==='debate'?'Biz tartışalım':'Oyun puan versin'}</small></span><span aria-hidden="true">＋</span></summary><div class="option-fields">${variantField()}${choices('slots','Kişi başına kart',[[3,'3 kart'],[5,'5 kart']])}${choices('budget','Başlangıç bütçesi',[[20,'20 jeton'],[30,'30 jeton'],[50,'50 jeton']])}${choices('timerSeconds','Her tekliften sonra süre',[[5,'5 saniye'],[10,'10 saniye'],[15,'15 saniye']])}${choices('scoring','Son sözü kim söylesin?', [['debate','Biz tartışalım'],['points','Oyun puan versin']])}<label class="fp-option"><span><strong>F/P yıldızları</strong><small>Kartı ne kadar iyi fiyata aldığını gör. Sonucu etkilemez.</small></span><input type="checkbox" name="pricePerformance" ${settings.pricePerformance?'checked':''}></label><label class="fp-option"><span><strong>Jokerli oyun</strong><small>Her turda herkese 1 joker. Açılış sırası sendeyken ilk tekliften önce kartı değiştir. Değişen kart yedek havuza döner.</small></span><input type="checkbox" name="jokers" ${settings.jokers?'checked':''}></label></div></details>`;}
function rules(){return `<details class="rules"><summary>Bir dakikada kurallar</summary><ul><li>Herkes eşit bütçeyle başlar. Kartlar sırayla ve sürpriz olarak açılır.</li><li>Açılış sırası dönüşür. İlk oyuncu 1 jetonla başlatır.</li><li>İlk tekliften sonra sıra yok: isteyen fiyatı 1 jeton artırabilir veya bu karttan çekilebilir. En yüksek teklif sahibi, başka biri artırana kadar bekler. Çekildiğin karta geri dönemezsin.</li><li>İlk tekliften sonra sayaç başlar; her yeni teklif süreyi sıfırlar. Süre dolunca veya herkes çekilince son teklif sahibi kartı alır. Kadron dolunca yeni kartlara teklif veremezsin.</li><li>Boş yerlerin için en az birer jeton saklanır. Fiyatı karşılayamayan oyuncu o karttan otomatik çekilir.</li><li>Yalnızca bir kişinin yeri kalırsa kalan kartları birer jetona alır.</li><li>Jokerler açıksa her turda herkese bir kart değiştirme hakkı verilir. Yalnızca açılış sırası sendeyken, ilk tekliften önce kullanılır; bütçen ve sıran değişmez. Değişen kart yedek havuza döner ve ileride yeniden çıkabilir.</li><li>Tartışma modunda kazananı siz seçersiniz. Puanlı modda kart puanları finalde toplanır.</li></ul></details>`;}
function inCategoryGroup(c){return group==='Hepsi'||group==='Yeni'&&c.fresh===true||c.group===group;}
function matchesCategory(c){return (c.name+' '+c.group+' '+c.brief).toLocaleLowerCase('tr-TR').includes(categoryQuery.trim().toLocaleLowerCase('tr-TR'));}
function filterCategoryCards(){let visible=0;for(const el of app.querySelectorAll('[data-category]')){const c=categoryById(el.dataset.category);el.hidden=!matchesCategory(c);if(!el.hidden)visible++;}const count=app.querySelector('[data-category-count]');if(count)count.textContent=visible+' kategori';const empty=app.querySelector('[data-category-empty]');if(empty)empty.hidden=visible>0;}
function home(){const c=categoryById(settings.categoryId);const resume=localGame?`<button class="resume" data-action="resume-local"><span><strong>Oyununa devam et</strong><small>${esc(categoryById(localGame.settings.categoryId)?.name||'Açık artırma')}</small></span><span aria-hidden="true">↗</span></button>`:'';const lanResume=session?`<button class="resume" data-action="resume-room"><span><strong>Odana dön</strong><small>${esc(session.code)}</small></span><span aria-hidden="true">↗</span></button>`:'';
if(homeStage==='categories')return `<section class="category-browser"><div class="browse-heading"><div><span class="eyebrow">01 / Kategorini seç</span><h1>Masaya ne koyuyoruz?</h1><p class="muted">Bütçen belli. Seçimlerin sana kalmış.</p></div><button class="btn secondary" data-action="join-room">Odaya katıl <span aria-hidden="true">↗</span></button></div><div class="resume-row">${resume}${lanResume}</div><div class="category-search"><label for="category-search">Kategori ara</label><div class="category-search-field"><span aria-hidden="true">⌕</span><input id="category-search" name="categoryQuery" type="search" value="${esc(categoryQuery)}" placeholder="Oyuncu, kahvaltı, futbol…" autocomplete="off"><span class="search-count" data-category-count>${categories.filter(c=>inCategoryGroup(c)&&matchesCategory(c)).length} kategori</span></div></div><nav class="filter-row" aria-label="Kategori grupları">${groups.map(g=>`<button data-group="${g}" class="${g===group?'active':''}" aria-pressed="${g===group}">${g}</button>`).join('')}</nav><div class="categories">${categories.filter(c=>inCategoryGroup(c)).map(c=>`<button class="category" data-category="${c.id}" ${matchesCategory(c)?'':'hidden'}>${photo(cover(c),'category-photo')}<span class="category-shade"></span><span class="category-group">${esc(c.group)}</span><span class="category-caption"><strong>${esc(c.name)}</strong><small>${c.cards.length} kart <span aria-hidden="true">↗</span></small></span></button>`).join('')}</div><p class="category-empty" data-category-empty ${categories.some(c=>inCategoryGroup(c)&&matchesCategory(c))?'hidden':''}>Bu aramada kategori bulunamadı. Başka bir kelime deneyebilirsin.</p></section>`;
return `<section class="setup-flow"><button class="back-link" data-action="browse">← Kategorilere dön</button><div class="setup-layout"><section class="selected-category">${mode==='join'?'':photo(cover(c),'setup-photo',true)}<div class="selected-caption"><span class="eyebrow">${mode==='join'?'Birlikte oynayın':'02 / Masanı kur'}</span><h1>${mode==='join'?'Masada yerin hazır.':esc(c.name)}</h1><p>${mode==='join'?'Oda kodunu gir, arkadaşlarına katıl.':esc(c.brief)}</p>${mode!=='join'?`<span class="pill">${c.cards.length} kart · Her oyunda yeni seçimler</span>`:''}</div></section><section class="panel" id="setup-panel"><h2>${mode==='join'?'Odaya katıl':'Nasıl oynayalım?'}</h2><div class="play-modes ${mode==='join'?'join-modes':''}" role="group" aria-label="Oynama şekli">${[['local','Tek telefon','İsminizi seçip teklif verin'],['create','Herkes kendi telefonunda','Aynı Wi-Fi üzerinde oda açın'],['join','Bir odaya katıl','Arkadaşının oda kodunu gir']].map(([id,title,desc])=>`<button class="play-mode ${mode===id?'active':''}" data-mode="${id}" aria-pressed="${mode===id}"><span class="mode-dot"></span><span><strong>${title}</strong><small>${desc}</small></span></button>`).join('')}</div>${mode==='join'&&session?.code===roomCode?lanResume:''}<form id="setup"><div class="fields">${mode==='join'?`<div><label for="join-code">Oda kodu</label><input id="join-code" class="code-input" name="code" placeholder="A7B92" value="${esc(roomCode)}" maxlength="5" autocapitalize="characters" autocomplete="off" required></div><div><label for="my-name">İsmin</label><input id="my-name" name="myName" value="${esc(myName)}" placeholder="Sana ne diyelim?" maxlength="24" autocomplete="nickname" required></div>`:`${mode==='local'?`<fieldset class="choice-field"><legend>Kaç kişiyiz?</legend><div class="choice-row count-choices">${[2,3,4,5,6].map(n=>`<button type="button" data-count="${n}" class="count-choice ${count===n?'active':''}" aria-pressed="${count===n}">${n}</button>`).join('')}</div></fieldset><div><label>Oyuncular</label><div class="name-grid">${names.slice(0,count).map((name,i)=>`<div class="name-field"><span>${i+1}</span><input aria-label="${i+1}. oyuncu ismi" name="player${i}" value="${esc(name)}" maxlength="24" autocomplete="off" required></div>`).join('')}</div></div>`:`<div><label for="my-name">İsmin</label><input id="my-name" name="myName" value="${esc(myName)}" placeholder="Sana ne diyelim?" maxlength="24" autocomplete="nickname" required></div>`}${mode==='local'?seriesUI.config(playPlan,settings,count,playlistPick):''}${settingsFields()}`}<button type="submit" class="btn lime wide">${mode==='local'?'Oyuna başlayalım':mode==='create'?'Odayı oluştur':'Masaya katıl'} <span aria-hidden="true">→</span></button></div></form><p class="fine">${mode==='local'?'Herkese eşit bütçe. Sıradaki kart her zaman sürpriz.':mode==='create'?'Herkes aynı Wi-Fi ağına bağlansın. Bu bilgisayar açık kalsın.':'Oda sahibinin paylaştığı bağlantıyı aç ve aynı Wi-Fi ağına bağlan.'}</p>${rules()}</section></div></section>`;}
function lobby(){const host=room.host,chosen=host?settings:room.settings,plan=host?playPlan:room.playPlan,c=categoryById(plan.mode==='playlist'&&plan.playlist.length?plan.playlist[0]:chosen.categoryId),link=roomLink();return `<section class="lobby"><div class="lobby-heading"><span class="eyebrow">${host?'Odan hazır':'Masaya katıldın'}</span><h1>${host?'Akşamı birlikte planlayın.':'Masada yerin hazır.'}</h1><p class="muted">${host?'Arkadaşlarını çağır, oyunları seç, seriyi başlat.':'Oda sahibi oyun akışını hazırlıyor.'}</p></div><div class="room-workspace"><aside class="room-sidebar"><section class="panel invite-panel"><div class="section-label"><h2>Arkadaşlarını çağır</h2><span class="pill">Aynı Wi-Fi</span></div><div class="room-code">${esc(room.code)}</div>${joinQR(link)}<button class="btn lime wide" data-action="share-link">Odayı paylaş ↗</button><button class="btn secondary wide" data-action="copy-link">Bağlantıyı kopyala</button><a class="room-link" href="${esc(link)}">${esc(link)}</a><p class="fine">Bağlantıyı açıp isimlerini yazmaları yeterli. Bu bilgisayar açık kalsın.</p></section>${chosen.television?tvInvite():''}<section class="panel members-panel"><div class="section-label"><h2>Masadakiler</h2><span class="pill">${room.members.length}/6</span></div>${room.members.map(m=>`<div class="lobby-player"><span class="avatar" aria-hidden="true">${esc(m.name[0])}</span><span class="member-name"><strong>${esc(m.name)}</strong><small>${m.host?'Oda sahibi':m.id===room.you?'Sen':'Oynamaya hazır'}</small></span>${host&&!m.host?`<button class="btn ghost" data-remove="${m.id}">Çıkar</button>`:''}</div>`).join('')}</section></aside><section class="panel room-planner">${host?`<form id="lobby-settings"><div class="fields">${seriesUI.config(plan,chosen,room.members.length,playlistPick)}${settingsFields()}<button class="btn lime wide" type="submit" ${room.members.length<2||plan.mode==='playlist'&&!plan.playlist.length?'disabled':''}>${room.members.length<2?'Bir kişi daha katılsın':plan.mode==='single'?'Herkes hazır, başlayalım':'Seriyi başlat'} →</button></div></form>`:`${seriesUI.preview(plan,chosen)}<p class="waiting-note">Oda sahibi başlayınca ilk kart açılacak.</p>`}<div class="room-category">${photo(cover(c),'room-category-photo')}<div><strong>${esc(c.name)}</strong><small>İlk tur · ${chosen.slots} kart · ${chosen.budget} jeton</small></div></div>${rules()}${connectionError?'<p class="connection">Bağlantı bekleniyor. Aynı Wi-Fi ağında olduğunuzu kontrol edin.</p>':''}</section></div></section>`;}
function tvLink(){return `${network[0]||location.origin}/?tv=${room.code}`;}
function tvInvite(){const link=tvLink();return `<section class="panel tv-invite"><span class="eyebrow">TV ekranı</span><h2>Salonu açık artırma salonuna çevir.</h2><p>TV’nin tarayıcısında bu bağlantıyı aç. Bilgisayarı TV’ye HDMI ile bağlayıp bu sayfayı açmak da olur.</p><a class="btn secondary wide" href="${esc(link)}" target="_blank" rel="noopener">TV ekranını aç ↗</a><button class="btn ghost wide" data-action="copy-tv-link">TV bağlantısını kopyala</button><a class="room-link" href="${esc(link)}" target="_blank" rel="noopener">${esc(link)}</a><small>TV oyuncu sayılmaz. Herkes telefonundan oynar.</small></section>`;}
function rosters(g,result=false){const best=g.settings.scoring==='points'&&result?Math.max(...g.players.map(p=>p.total)):null;return `<section class="rosters" aria-label="Oyuncuların kadroları">${g.players.map(p=>`<article class="roster ${p.id===g.turnId?'active':''} ${result?'result':''} ${p.total===best&&best!==null?'winner':''}"><div class="roster-top"><span class="avatar" aria-hidden="true">${esc(p.name[0])}</span><div><strong>${esc(p.name)}${transport==='lan'&&room.you===p.id?' · Sen':''}</strong><small>${p.budget} jeton · ${p.cards.length}/${g.settings.slots} kart${g.settings.jokers?' · '+(p.jokersLeft||0)+' joker':''}</small></div></div>${p.total!==null?`<div class="score">${p.total}<span style="font-size:.9rem;font-weight:500"> puan</span></div>`:''}${p.cards.map(c=>`<div class="roster-card">${photo(c,'roster-photo')}<span class="roster-card-name">${esc(c.name)}${g.settings.pricePerformance&&c.deal?`<small class="roster-deal" aria-label="F/P ${c.deal.stars}/5">${'★'.repeat(c.deal.stars)}${'☆'.repeat(5-c.deal.stars)}</small>`:''}</span><span>${c.paid} j${result&&g.settings.scoring==='points'?'<br>'+c.score+' p':''}</span></div>`).join('')}${Array.from({length:g.settings.slots-p.cards.length},()=>'<div class="empty-slot">Henüz boş</div>').join('')}</article>`).join('')}</section>`;}
function gameUI(){const s=currentSeries(),host=transport==='local'||room.host;if(s?.phase==='voting'){localVoter=s.players.some(p=>p.id===localVoter)?localVoter:s.players[0].id;return seriesUI.vote(s,room?.you,transport==='local',localVoter);}const g=transport==='local'?viewGame(localGame):room.game;if(s?.phase==='finished')return auctionUI.receipt(g,{compact:true})+seriesUI.final(s,host);const c=categoryById(g.settings.categoryId);if(g.status==='finished')return results(g,c);const shared=transport==='local';if(!canBid(g,sharedBidderId))sharedBidderId=null;const actorId=shared?(g.price===0?g.turnId:sharedBidderId):room.you,canNext=shared||room.host,cap=maxBid(g,actorId);
 if(g.settings.television&&transport==='lan')return `${s?seriesUI.progress(s):''}${connectionError?'<div class="connection">Bağlantı bekleniyor.</div>':''}${tvUI.controller(g,{you:room.you,busy,connectionError,cap: maxBid(g,room.you)})}`;
 const key=(s?.round||1)+':'+g.current.id+':'+g.turnId+':'+g.status,flash=key!==turnFlashKey;turnFlashKey=key;
 return `${s?seriesUI.progress(s):''}${connectionError?'<div class="connection" role="status">Bağlantı yeniden kuruluyor. Teklifler bağlantı gelince devam edecek.</div>':''}${auctionUI.stage(g,c,{cap,canNext,busy,connectionError,flash,shared,actorId,you:transport==='lan'?room.you:null})}<div class="collection-heading"><h2>Masadaki kadrolar</h2><span>Herkesin bütçesi ve seçimleri</span></div>${rosters(g)}${s?`<details class="series-score-peek"><summary>Genel sıralama</summary>${seriesUI.board(s)}</details>`:''}${rules()}`;}
function results(g,c){const s=currentSeries(),host=transport==='local'||room.host;if(s){const key=s.round+':'+g.current.id;if(key!==rankKey){rankKey=key;rankDraft={};}}const ranked=[...g.players].sort((a,b)=>(b.total||0)-(a.total||0)),winning=ranked.filter(p=>p.total===ranked[0].total).map(p=>p.name),title=g.settings.scoring==='debate'?'Son söz sizde.':winning.length>1?'Puanlar eşit.':winning[0]+' kazandı.';
return `${s?seriesUI.progress(s):''}${auctionUI.receipt(g,{compact:true})}<section class="result-banner"><span class="eyebrow">${esc(c.name)} · ${s?'Tur sonucu':'Final'}</span><h1>${esc(title)}</h1><p>${g.settings.scoring==='debate'?'Herkesin seçimleri burada. Sence en iyi kadro kimde? Anlaşamazsanız beraberlik de olur.':esc(winning.length>1?'Bu maçın en yüksek puanı '+ranked[0].total+'.':c.metric+': '+ranked[0].total)}</p><div class="result-actions">${!s&&host?'<button class="btn lime" data-action="rematch">Bir daha oynayalım</button>':''}<button class="btn secondary" data-action="copy-prompt">ChatGPT promptunu kopyala</button><button class="btn ghost" data-action="copy-result">Sadece takımları kopyala</button><button class="btn ghost" data-action="home">Kategorilere dön</button></div></section>${rosters(g,true)}${s?seriesUI.roundControls(s,host,rankDraft):''}${g.settings.scoring==='points'?`<details class="rules score-explanation" open><summary>Puanlar nasıl hesaplandı?</summary><p>${esc(c.basis)}</p><p>${esc(scoringNote)}</p></details>`:`<p class="fine">${s?'Tur sıralamasını oda sahibi kaydeder; seri puanları buna göre eklenir.':'Bu modda oyun puan hesaplamaz ve kazanan ilan etmez.'}</p>`}`;}
function roomLink(){return `${network[0]||location.origin}/?room=${room.code}`;}
function timerUI(g){return `<div class="auction-timer ${g.price===0?'waiting':''}" aria-label="Teklif geri sayacı"><div class="timer-label"><span data-timer-label>${g.status==='sold'?'Kart alındı':g.price===0?'İlk teklif bekleniyor':'Yeni teklif için'}</span><strong data-timer-number></strong></div><div class="timer-track"><span data-timer-bar></span></div><small>${g.status==='sold'?'Sonraki kart yeni bir açık artırma başlatır.':'Her yeni teklif süreyi sıfırlar.'}</small></div>`;}
function activityUI(g){const events=(g.activity||[]).filter(a=>a.cardId===g.current.id).slice(0,3);const key=events[0]?g.current.id+':'+events[0].seq:'';if(key&&key!==seenActivity)animationUntil=Date.now()+600;seenActivity=key;return `<section class="bid-activity" aria-label="Son teklifler"><h3>Masada şimdi</h3>${events.length?events.map((a,i)=>`<p class="activity-row ${i===0&&key&&Date.now()<animationUntil?'just-bid':''}"><span class="activity-dot"></span><span><strong>${esc(a.name)}</strong> ${a.type==='bid'?a.amount+' jeton teklif verdi':a.type==='joker'?'jokerle kartı değiştirdi':'bu karttan çekildi'}</span></p>`).join(''):`<p class="fine">${g.status==='sold'?'Bu kart sonuçlandı.':'İlk teklif burada görünecek.'}</p>`}</section>`;}
function currentGame(){return transport==='local'?localGame:room?.game;}
function tick(){if(screen!=='game')return;if(transport==='local'&&syncLocal()){render();return;}const s=currentSeries(),g=currentGame();if(!g)return;const now=Date.now()+(transport!=='local'?clockOffset:0);
 if(s?.phase==='voting'){const remaining=s.vote.deadline?Math.max(0,s.vote.deadline-now):null,number=app.querySelector('[data-vote-timer]');if(number)number.textContent=remaining==null?'İlk oy bekleniyor':remaining===0?'Yeni tur hazırlanıyor':Math.ceil(remaining/1000)+' sn';sounds.clock('vote:'+s.vote.round+':'+s.vote.deadline,remaining);if(remaining===0)for(const b of app.querySelectorAll('[data-vote-category]'))b.disabled=true;return;}
 if(g.status==='countdown'){const remaining=Math.max(0,g.revealDeadline-now);for(const el of app.querySelectorAll('[data-reveal-number]'))el.textContent=remaining?Math.ceil(remaining/1000):'Hazır';sounds.clock('reveal:'+g.revealDeadline,remaining);if(tvCode!==null)announcer.count('reveal:'+g.revealDeadline,remaining);return;}
 if(g.status==='sold'&&g.autoNextAt){const remaining=Math.max(0,g.autoNextAt-now);for(const el of app.querySelectorAll('[data-next-number]'))el.textContent=Math.ceil(remaining/1000)+' sn';}
 if(g.status==='finished')return;const remaining=g.status==='bidding'&&g.deadline?Math.max(0,g.deadline-now):null;
 const number=app.querySelector('[data-timer-number]'),bar=app.querySelector('[data-timer-bar]'),timer=app.querySelector('.auction-timer');
 if(number)number.textContent=remaining===null?'':Math.ceil(remaining/1000)+' sn';
 if(bar)bar.style.width=(remaining===null?0:Math.min(100,remaining/((g.settings.timerSeconds??10)*1000)*100))+'%';timer?.classList.toggle('urgent',remaining!==null&&remaining<=3000);
 sounds.clock((s?.round||1)+':'+(g.current?.id||g.deck?.[g.index]?.id)+':'+g.deadline,remaining);
 if(remaining===0){const label=app.querySelector('[data-timer-label]');if(label)label.textContent='Süre doldu · Kart sonuçlanıyor';for(const b of app.querySelectorAll('[data-action="bid"],[data-action="pass"]'))b.disabled=true;}
}
function tableDetails(){const g=transport==='local'?viewGame(localGame):room?.game;if(!g)return '';const s=currentSeries(),deal=g.settings.pricePerformance?g.lastSale?.card.deal:null;return `<div class="modal-shade table-details-shade"><section class="table-dialog" role="dialog" aria-modal="true" aria-labelledby="table-details-title"><header><h2 id="table-details-title">Masadaki detaylar</h2><button class="btn ghost" data-action="close-table-details" aria-label="Detayları kapat">×</button></header><div class="table-dialog-content"><div class="detail-card-intro">${g.current?`${photo(g.current,'detail-photo')}<div><h3>${esc(g.current.name)}</h3><p>${esc(cardInfo(g.current).text)}</p></div>`:'<h3>Sıradaki kart birazdan açılacak.</h3>'}</div>${deal?`<section class="detail-fp"><h3>Son alış · F/P ${deal.stars}/5</h3><p>${esc(g.lastSale.name)}, ${esc(g.lastSale.card.name)} kartını ${g.lastSale.card.paid} jetona aldı. Oyun değerine ve başlangıç bütçesine göre referans fiyat yaklaşık ${deal.referencePrice} jeton. Yıldızlar kadro ve seri puanını değiştirmez.</p></section>`:''}${rosters(g)}${activityUI(g)}${s?seriesUI.board(s):''}${rules()}</div></section></div>`;}
function notificationSettings(){const prefs=turnNotice.preferences;return `<div class="modal-shade notice-settings-shade"><section class="modal notice-dialog" role="dialog" aria-modal="true" aria-labelledby="notice-title"><header><h2 id="notice-title">Açılışını kaçırma.</h2><button class="btn ghost" data-action="close-notices" aria-label="Bildirim ayarlarını kapat">×</button></header><p>İlk teklif sırası sana gelince bu telefonda haber verelim. Sonraki teklifler serbest.</p>${[['sound','Kısa ses','Ses açık olduğunda açılış için küçük bir melodi.'],['vibration','Titreşim',turnNotice.vibrationSupported?'Açılış sırası sana gelince iki kısa titreşim.':'Bu cihazda titreşim desteklenmiyor; ses ve ekran bildirimi kullanılabilir.'],['visual','Ekran bildirimi','Oyunu kaydırmadan Açılış sende uyarısı.']].map(([key,title,description])=>`<label class="fp-option"><span><strong>${title}</strong><small>${description}</small></span><input type="checkbox" name="notice:${key}" ${prefs[key]?'checked':''} ${key==='vibration'&&!turnNotice.vibrationSupported?'disabled':''}></label>`).join('')}<button class="btn secondary wide" data-action="preview-notice">Bildirimi dene</button><p class="fine">Bu seçenekler sadece bu cihazda saklanır. Tek telefonda her kartın açılış sırası bildirilir.</p></section></div>`;}
function render(){if(tvCode!==null){renderDisplay();return;}const noticeFocus=noticeSettingsOpen?document.activeElement?.name:null;const detailScroll=app.querySelector('.table-dialog-content')?.scrollTop||0;if(screen==='game'&&transport==='local')syncLocal();const series=currentSeries(),game=currentGame(),playing=screen==='game'&&game&&game.status!=='finished'&&(!series||series.phase==='playing');app.innerHTML=`<main class="shell ${playing?'playing-shell':''}"><header class="topbar"><button class="brand" data-action="home" aria-label="Teklif ana ekran"><span class="brand-mark">T</span>teklif</button><div class="top-controls"><button class="nav-action sound-switch" data-action="sound" aria-pressed="${sounds.enabled}">${sounds.enabled?'Ses açık ♪':'Ses kapalı'}</button><button class="nav-action notice-switch" data-action="notice-settings" aria-label="Sıra bildirim ayarları">Bildirim</button>${screen!=='home'?`<button class="nav-action" data-action="home">Yeni oyun</button>${transport==='lan'&&room?'<button class="nav-action" data-action="share-link">Odayı paylaş ↗</button>':''}`:''}<span class="top-note">${transport==='lan'&&room&&screen!=='home'?'Oda '+esc(room.code):'Aynı masa. Farklı seçimler.'}</span></div></header>${screen==='home'?home():screen==='lobby'?lobby():gameUI()}<footer class="footnote"><span>Teklif · İlk oynanabilir sürüm</span><span>Oyun jetonlarıyla oynanır.</span></footer>${tableDetailsOpen&&screen==='game'?tableDetails():''}${noticeSettingsOpen?notificationSettings():''}</main>`;if(tableDetailsOpen){const content=app.querySelector('.table-dialog-content');if(content)content.scrollTop=detailScroll;for(const child of app.querySelector('.shell').children)if(!child.classList.contains('table-details-shade'))child.inert=true;}if(noticeSettingsOpen){for(const child of app.querySelector('.shell').children)if(!child.classList.contains('notice-settings-shade'))child.inert=true;if(noticeFocus)app.querySelector(`[name="${noticeFocus}"]`)?.focus({preventScroll:true});}if(screen==='game')sounds.observe(transport==='local'?viewGame(localGame):room?.game,currentSeries(),transport==='lan'?room.you:null);observeTurn();tick();}
function observeTurn(){turnNotice.observe(screen==='game'&&(!currentSeries()||currentSeries().phase==='playing')?currentGame():null,{you:transport==='lan'?room?.you:null,shared:transport==='local',scope:transport==='lan'?room?.code:'local',round:currentSeries()?.round||1,connected:!connectionError});}
function renderDisplay(){
 document.body.classList.add('television-display');
 const g=room?.game,s=room?.series;
 app.innerHTML=`<main class="tv-shell"><header class="tv-header"><span class="brand"><span class="brand-mark">T</span>teklif <small>TV</small></span><span>${room?'Oda '+esc(room.code)+(s?' · Tur '+s.round+' / '+s.totalRounds:''):''}</span><div><button class="nav-action" data-action="announcer" aria-pressed="${announcer.enabled}" ${announcer.available?'':'disabled'}>${announcer.available?announcer.enabled?'Sunucu sesi açık':'Sunucu sesi aç':'Sunucu sesi desteklenmiyor'}</button><button class="nav-action" data-action="sound" aria-pressed="${sounds.enabled}">${sounds.enabled?'Ses açık ♪':'Ses kapalı'}</button><button class="nav-action" data-action="fullscreen">Tam ekran ↗</button></div></header>${room?(g?tvUI.display(room,categoryById):tvUI.lobby(room,roomLink())):`<section class="tv-interlude"><span class="tv-kicker">Büyük ekran, ortak heyecan</span><h1>${connectionError?'Odaya bağlanamadık.':'TV’de oyna.'}</h1><p>${connectionError?'Oda kodunu ve aynı Wi-Fi’ye bağlı olduğunuzu kontrol edin. Oda sahibi TV seçeneğini açmış olmalı.':'Telefonundan oda kur, TV’de oyna seçeneğini aç ve kodunu buraya gir.'}</p><form id="tv-connect"><input name="tvCode" aria-label="TV oda kodu" maxlength="5" placeholder="Oda kodu" value="${esc(tvCode)}" required><button class="btn lime" type="submit">Ekranı bağla →</button></form></section>`}${connectionError&&room?'<div class="tv-connection" role="status">Bağlantı bekleniyor · Son durum gösteriliyor</div>':''}</main>`;
 if(g){sounds.observe(g,s,null);announcer.observe(g,s);tick();}
}
async function loadDisplay(){if(!/^[A-Z0-9]{5}$/.test(tvCode)||busy)return;try{const data=await api('/api/rooms/'+tvCode+'/screen'),{serverNow,...stable}=data,serialized=JSON.stringify(stable),changed=serialized!==lastSnapshot||connectionError;room=data;connectionError=false;lastSnapshot=serialized;if(changed)renderDisplay();}catch{if(!connectionError){connectionError=true;renderDisplay();}}}
function readSettings(f){return {categoryId:String(f.get('categoryId')),slots:Number(f.get('slots')),budget:Number(f.get('budget')),timerSeconds:Number(f.get('timerSeconds')||10),scoring:String(f.get('scoring')),television:f.has('television'),pricePerformance:f.has('pricePerformance'),jokers:f.has('jokers'),variant:f.get('variant')||'all'};}
async function api(endpoint,options={}){const started=Date.now();const headers={'Content-Type':'application/json'};if(session?.token)headers['X-Player-Token']=session.token;const r=await fetch(endpoint,{...options,headers,signal:typeof AbortSignal.timeout==='function'?AbortSignal.timeout(8000):undefined});const data=await r.json();if(data.serverNow)clockOffset=data.serverNow-(started+Date.now())/2;if(!r.ok){const error=new Error(data.error||'İşlem tamamlanamadı.');error.status=r.status;throw error;}return data;}
function applyRoom(data){if(room?.code===data.code&&data.serverNow<room.serverNow)return;const {serverNow,...stable}=data;const serialized=JSON.stringify(stable);const changed=serialized!==lastSnapshot||connectionError;room=data;if(!data.host&&data.phase==='lobby'){settings={...data.settings};playPlan={...data.playPlan};}connectionError=false;lastSnapshot=serialized;if(screen!=='home')screen=data.phase==='lobby'?'lobby':'game';if(changed&&screen!=='home')render();}
async function resumeRoom(){if(!session)return;try{const data=await api('/api/rooms/'+session.code);transport='lan';screen=data.phase==='lobby'?'lobby':'game';settings={...data.settings};playPlan={...data.playPlan};if(playPlan.mode==='vote')voteRounds=playPlan.rounds;playlistPick=settings.categoryId;applyRoom(data);render();}catch(err){toast(err.message);if(err.status===400){session=null;storage.remove('teklif-session');}render();}}
async function poll(){if(polling||busy||tvCode===null&&(transport!=='lan'||!session||screen==='home'))return;const now=Date.now(),interval=tvCode!==null||room?.settings.television||room?.game?.status==='bidding'?250:1000;if(now-lastPollAt<interval)return;lastPollAt=now;polling=true;try{if(tvCode!==null)await loadDisplay();else{const data=await api('/api/rooms/'+session.code);if(!busy)applyRoom(data);}}catch{if(!connectionError){connectionError=true;render();}}finally{polling=false;}}
async function sendAction(type,amount){if(busy)return;busy=true;try{if(transport==='local'){act(localGame,localGame.price===0?localGame.turnId:sharedBidderId,type,amount,localGame.revision);syncLocal();saveLocal();}else applyRoom(await api(`/api/rooms/${session.code}/action`,{method:'POST',body:JSON.stringify({type,amount,revision:room.game.revision})}));if(type==='bid')sounds.play('bid');else if(type==='joker')sounds.play('card');}catch(err){toast(err.message);if(transport==='local')saveLocal();else await pollAfterError();}finally{busy=false;render();}}
async function seriesAction(type,payload={}){if(busy)return;busy=true;try{
 const s=currentSeries();if(transport==='local'){const holder={game:localGame,series:localSeries};if(type==='rank')rankRound(holder,payload.placements,s.revision);else if(type==='series-next')advanceSeries(holder,s.revision);else if(type==='vote')castVote(holder,localVoter,payload.categoryId,s.vote.round);localGame=holder.game;localSeries=holder.series;syncLocal();saveLocal();}else applyRoom(await api(`/api/rooms/${session.code}/${type}`,{method:'POST',body:JSON.stringify({...payload,revision:s.revision,round:s.vote?.round})}));if(type==='vote')sounds.play('vote');
 }catch(error){toast(error.message);if(transport==='lan')await pollAfterError();}finally{busy=false;render();if(type!=='vote')window.scrollTo(0,0);}}
async function pollAfterError(){try{applyRoom(await api('/api/rooms/'+session.code));}catch{connectionError=true;}}
function confirm(message,action){confirmAction=action;const wrap=document.createElement('div');wrap.className='modal-shade';wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><h2 id="confirm-title">${esc(message)}</h2><div class="actions"><button class="btn lime" data-action="confirm">Evet, devam</button><button class="btn ghost" data-action="cancel">Vazgeç</button></div></section>`;app.append(wrap);wrap.querySelector('[data-action="cancel"]').focus();}
async function copy(text){try{
 if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);
 else{
  const previous=document.activeElement,f=document.createElement('textarea');f.value=text;f.readOnly=true;f.style.cssText='position:fixed;left:-9999px;top:0;font-size:16px';document.body.append(f);
  const write=e=>{if(e.clipboardData){e.clipboardData.setData('text/plain',text);e.preventDefault();}};
  document.addEventListener('copy',write);let ok=false;
  try{f.focus({preventScroll:true});f.select();f.setSelectionRange(0,text.length);ok=document.execCommand('copy');}
  finally{document.removeEventListener('copy',write);f.remove();previous?.focus({preventScroll:true});}
  if(!ok)throw new Error();
 }
 toast('Kopyalandı.');return true;
 }catch{
  const wrap=document.createElement('div');wrap.className='modal-shade';wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="Metni kopyala"><h2>Metni seçip kopyalayabilirsin</h2><textarea class="copy-text" readonly aria-label="Kopyalanacak metin">${esc(text)}</textarea><button class="btn secondary wide" data-action="cancel">Kapat</button></section>`;app.append(wrap);wrap.querySelector('textarea').select();return false;
 }
}
app.addEventListener('error',e=>{if(e.target.tagName==='IMG'){e.target.hidden=true;const note=e.target.parentElement.querySelector('.photo-unavailable');if(note)note.hidden=false;}},true);
app.addEventListener('toggle',e=>{if(e.target.classList?.contains('game-options'))advancedOpen=e.target.open;},true);
app.addEventListener('input',e=>{const {name,value}=e.target;if(name==='categoryQuery'){categoryQuery=value;filterCategoryCards();}else if(name?.startsWith('player'))names[Number(name.slice(6))]=value;else if(name==='myName')myName=value;else if(name==='code')roomCode=value.toUpperCase();});
app.addEventListener('change',e=>{const {name,value}=e.target;
 if(name==='bidderId'){sharedBidderId=value||null;render();app.querySelector('[name="bidderId"]')?.focus({preventScroll:true});return;}
 if(name?.startsWith('notice:')){storage.set('teklif-turn-notice',turnNotice.setPreferences({[name.slice(7)]:e.target.checked}));return;}
 if(name?.startsWith('rank:')){rankDraft[name.slice(5)]=Number(value);return;}
 if(name==='playlist-category'){playlistPick=value;return;}
 if(name==='seriesRounds'){voteRounds=Number(value);playPlan.rounds=voteRounds;render();configureLobby();return;}
 if(name==='pricePerformance'||name==='television'||name==='jokers'){settings[name]=e.target.checked;render();configureLobby();return;}
 if(['categoryId','variant','slots','budget','timerSeconds','scoring'].includes(name)){settings[name]=['slots','budget','timerSeconds'].includes(name)?Number(value):value;if(name==='categoryId'){settings.variant='all';playlistPick=value;}render();configureLobby();}
});
app.addEventListener('click',async e=>{
 sounds.unlock();turnNotice.unlock();
 if(tvCode!==null){const action=e.target.closest('[data-action]')?.dataset.action;if(action==='announcer'){announcer.toggle();render();}else if(action==='sound'){storage.set('teklif-sound',sounds.toggle());render();}else if(action==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Tam ekran bu tarayıcıda desteklenmiyor. TV ekranı yine kullanılabilir.');}}return;}
 const planMode=e.target.closest('[data-plan-mode]');if(planMode){playPlan.mode=planMode.dataset.planMode;if(playPlan.mode==='vote')playPlan.rounds=voteRounds;if(playPlan.mode==='playlist'&&!playPlan.playlist.length)playPlan.playlist=[settings.categoryId];render();configureLobby();return;}
 const listOp=e.target.closest('[data-list-op]');if(listOp){if(listOp.disabled)return;const i=Number(listOp.dataset.index),op=listOp.dataset.listOp;if(op==='remove')playPlan.playlist.splice(i,1);else{const to=i+(op==='up'?-1:1);[playPlan.playlist[i],playPlan.playlist[to]]=[playPlan.playlist[to],playPlan.playlist[i]];}render();configureLobby();return;}
 const voter=e.target.closest('[data-voter]');if(voter){localVoter=voter.dataset.voter;render();return;}
 const vote=e.target.closest('[data-vote-category]');if(vote){if(!vote.disabled)await seriesAction('vote',{categoryId:vote.dataset.voteCategory});return;}
 const c=e.target.closest('[data-category]');if(c){settings.categoryId=c.dataset.category;settings.variant='all';playlistPick=settings.categoryId;if(playPlan.mode==='playlist')playPlan.playlist=[settings.categoryId];homeStage='setup';if(mode==='join')mode='local';render();window.scrollTo(0,0);return;}const people=e.target.closest('[data-count]');if(people){count=Number(people.dataset.count);render();return;}const g=e.target.closest('[data-group]');if(g){group=g.dataset.group;render();return;}const m=e.target.closest('[data-mode]');if(m){mode=m.dataset.mode;render();return;}const remove=e.target.closest('[data-remove]');if(remove){confirm('Bu oyuncu odadan çıkarılsın mı?',async()=>{try{applyRoom(await api(`/api/rooms/${session.code}/remove`,{method:'POST',body:JSON.stringify({id:remove.dataset.remove})}));}catch(err){toast(err.message);}});return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;try{
if(action==='notice-settings'){noticeSettingsOpen=true;tableDetailsOpen=false;render();app.querySelector('[data-action="close-notices"]')?.focus({preventScroll:true});}
else if(action==='close-notices'){noticeSettingsOpen=false;render();app.querySelector('[data-action="notice-settings"]')?.focus({preventScroll:true});}
else if(action==='preview-notice')turnNotice.preview();
else if(action==='table-details'){tableDetailsOpen=true;render();app.querySelector('[data-action="close-table-details"]')?.focus({preventScroll:true});}
else if(action==='close-table-details'){tableDetailsOpen=false;render();app.querySelector('[data-action="table-details"]')?.focus({preventScroll:true});}
else if(action==='sound'){storage.set('teklif-sound',sounds.toggle());render();}
else if(action==='playlist-add'){if(playPlan.playlist.length<10){playPlan.playlist.push(playlistPick);render();configureLobby();}}
else if(action==='series-next')await seriesAction('series-next');
else if(action==='copy-series'||action==='copy-series-prompt'){const s=currentSeries();await copy(seriesSummary(s)+'\n\n'+s.results.map(r=>action==='copy-series-prompt'?analysisPrompt(r.game):formatTeams(r.game)).join('\n\n———\n\n')+(action==='copy-series-prompt'?'\n\nSeri puanları yukarıdaki sıralamalardan verildi. Tüm turları ayrı ayrı değerlendir; genel performansı ve kategori çeşitliliğini yorumla. Puan toplamlarını değiştirme.':''));}
else if(action==='home'){tableDetailsOpen=false;screen='home';homeStage='categories';render();window.scrollTo(0,0);}
else if(action==='browse'){homeStage='categories';render();window.scrollTo(0,0);}
else if(action==='join-room'){mode='join';homeStage='setup';render();window.scrollTo(0,0);}
else if(action==='resume-local'){if(!localGame)return;transport='local';screen='game';syncLocal();render();window.scrollTo(0,0);}
else if(action==='resume-room')await resumeRoom();
else if(['bid','pass','next','joker'].includes(action))await sendAction(action,Number(b.dataset.amount));
else if(action==='rematch'){if(transport==='local'){if(localSeries){settings={...localSeries.settings};playPlan={mode:localSeries.mode,playlist:[...localSeries.playlist],rounds:localSeries.totalRounds};voteRounds=playPlan.rounds;playlistPick=settings.categoryId;count=localGame.players.length;names=localGame.players.map(p=>p.name);mode='local';screen='home';homeStage='setup';render();window.scrollTo(0,0);}else{settings={...localGame.settings};const holder=startMatch(settings,localGame.players.map(p=>({id:p.id,name:p.name})),{mode:'single'});localGame=holder.game;localSeries=null;saveLocal();render();window.scrollTo(0,0);}}else{const data=await api(`/api/rooms/${session.code}/restart`,{method:'POST',body:'{}'});settings={...data.settings};playPlan={...data.playPlan};applyRoom(data);}}
else if(action==='copy-tv-link')await copy(tvLink());
else if(action==='copy-link')await copy(roomLink());
else if(action==='share-link'){const url=roomLink();if(navigator.share&&window.isSecureContext){try{await navigator.share({title:'Teklif · Masaya katıl',text:'Aynı Wi-Fi’ye bağlanıp masama katıl. Oda kodu: '+room.code,url});}catch(error){if(error.name!=='AbortError')await copy(url);}}else if(await copy(url))toast('Oda bağlantısı kopyalandı. Arkadaşlarına gönderebilirsin.');}
else if(action==='copy-result'||action==='copy-prompt'){const game=transport==='local'?viewGame(localGame):room.game;await copy(action==='copy-prompt'?analysisPrompt(game):formatTeams(game));}
else if(action==='cancel'){confirmAction=null;app.querySelector('.modal-shade')?.remove();}
else if(action==='confirm'){const run=confirmAction;confirmAction=null;app.querySelector('.modal-shade')?.remove();await run?.();}
}catch(err){toast(err.message);}});
async function seriesActionUnlockedRank(f){const s=currentSeries(),placements=s.players.map(p=>({id:p.id,rank:Number(f.get('rank:'+p.id))}));if(transport==='local'){rankRound({game:localGame,series:localSeries},placements,s.revision);saveLocal();}else applyRoom(await api(`/api/rooms/${session.code}/rank`,{method:'POST',body:JSON.stringify({placements,revision:s.revision})}));window.scrollTo(0,0);}
app.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const f=new FormData(e.target);busy=true;try{
if(e.target.id==='tv-connect'){const code=String(f.get('tvCode')||'').trim().toUpperCase();if(!/^[A-Z0-9]{5}$/.test(code))throw new Error('Beş haneli oda kodunu gir.');location.href='/?tv='+encodeURIComponent(code);}
else if(e.target.id==='round-ranking'){await seriesActionUnlockedRank(f);}
else if(e.target.id==='lobby-settings'){settings=readSettings(f);await configQueue;applyRoom(await api(`/api/rooms/${session.code}/start`,{method:'POST',body:JSON.stringify({settings,playPlan})}));window.scrollTo(0,0);}
else if(e.target.id==='setup'){
if(mode==='local'){settings=readSettings(f);const people=Array.from({length:count},(_,i)=>({id:'p'+i,name:f.get('player'+i)}));const begin=()=>{const holder=startMatch(settings,people,playPlan);localGame=holder.game;localSeries=holder.series;saveLocal();transport='local';screen='game';syncLocal();render();window.scrollTo(0,0);};if(localGame&&(localGame.status!=='finished'||localSeries&&localSeries.phase!=='finished'))confirm('Önceki masanın yerine yeni oyun başlasın mı?',begin);else begin();}
else{if(mode==='create')settings=readSettings(f);myName=String(f.get('myName')).trim();const endpoint=mode==='create'?'/api/rooms':`/api/rooms/${String(f.get('code')).trim().toUpperCase()}/join`;const data=await api(endpoint,{method:'POST',body:JSON.stringify({name:myName,settings,playPlan})});session={code:data.code,token:data.token};storage.set('teklif-session',session);transport='lan';screen='lobby';settings={...data.settings};playPlan={...data.playPlan};if(playPlan.mode==='vote')voteRounds=playPlan.rounds;playlistPick=settings.categoryId;applyRoom(data);render();window.scrollTo(0,0);}}
}catch(err){toast(err.message);}finally{busy=false;if(!confirmAction)render();}});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&(tableDetailsOpen||noticeSettingsOpen)){const dialog=app.querySelector(noticeSettingsOpen?'.notice-dialog':'.table-dialog'),controls=[...dialog.querySelectorAll('button,a,summary,select,input')].filter(el=>!el.disabled&&el.getClientRects().length),first=controls[0],last=controls.at(-1);if(e.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){e.preventDefault();last?.focus({preventScroll:true});}else if(!e.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){e.preventDefault();first?.focus({preventScroll:true});}}if(e.key==='Escape'&&app.querySelector('.modal-shade')){if(noticeSettingsOpen){noticeSettingsOpen=false;render();app.querySelector('[data-action="notice-settings"]')?.focus({preventScroll:true});return;}if(tableDetailsOpen){tableDetailsOpen=false;render();app.querySelector('[data-action="table-details"]')?.focus({preventScroll:true});return;}confirmAction=null;app.querySelector('.modal-shade')?.remove();}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden){tick();poll();if(tvCode===null)observeTurn();}});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_auction_state',title:'Açık artırma durumunu oku',description:'Read the currently visible auction without revealing upcoming cards.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('No parameters accepted.');return {screen,transport,game:screen==='game'?(transport==='local'?viewGame(localGame):room?.game):null,series:screen==='game'?currentSeries():null,playPlan:screen==='lobby'?room?.playPlan:null,categories:categories.map(c=>({id:c.id,name:c.name,cards:c.cards.length}))};}});}catch{}}
if(tvCode!==null){screen='game';transport='display';}
render();if(tvCode!==null)loadDisplay();else if(roomCode&&session?.code===roomCode)resumeRoom();fetch('/api/network').then(r=>r.json()).then(data=>{network=data.urls||[];if(screen==='lobby'||tvCode!==null)render();}).catch(()=>{});setInterval(poll,250);setInterval(tick,100);
